277	    public function syncPaymentMethodFromCheckoutSession(Professional $brand, string $sessionId): array
278	    {
279	        $session = $this->stripe->checkout->sessions->retrieve($sessionId, [
280	            'expand' => ['setup_intent'],
281	        ]);
282	
283	        if (($session->mode ?? null) !== 'setup') {
284	            throw new \RuntimeException('Checkout session is not a setup session.');
285	        }
286	
287	        if (($session->status ?? null) !== 'complete') {
288	            throw new \RuntimeException('Setup session is not complete yet.');
289	        }
290	
291	        $metadataProId = $session->metadata?->sidest_professional_id ?? null;
292	        if ($metadataProId && $metadataProId !== $brand->id) {
293	            throw new \RuntimeException('Setup session does not belong to this account.');
294	        }
295	
296	        $sessionCustomerId = is_string($session->customer)
297	            ? $session->customer
298	            : ($session->customer->id ?? null);
299	
300	        if ($brand->stripe_customer_id && $sessionCustomerId && $brand->stripe_customer_id !== $sessionCustomerId) {
301	            throw new \RuntimeException('Setup session customer does not match account customer.');
302	        }
303	
304	        if (! $brand->stripe_customer_id && $sessionCustomerId) {
305	            $brand->update(['stripe_customer_id' => $sessionCustomerId]);
306	            $brand->refresh();
307	        }
308	
309	        $setupIntentId = is_string($session->setup_intent)
310	            ? $session->setup_intent
311	            : ($session->setup_intent->id ?? null);
312	
313	        if (! $setupIntentId) {
314	            throw new \RuntimeException('Setup session missing setup intent.');
315	        }
316	
317	        $setupIntent = $this->stripe->setupIntents->retrieve($setupIntentId, [
318	            'expand' => ['payment_method'],
319	        ]);
320	
321	        if (($setupIntent->status ?? null) !== 'succeeded') {
322	            throw new \RuntimeException('Setup intent has not succeeded.');
323	        }
324	
325	        $paymentMethodId = is_string($setupIntent->payment_method)
326	            ? $setupIntent->payment_method
327	            : ($setupIntent->payment_method->id ?? null);
328	
329	        if (! $paymentMethodId) {
330	            throw new \RuntimeException('No payment method found on setup intent.');
331	        }
332	
333	        $this->savePaymentMethod($brand, $paymentMethodId);
334	
335	        return [
336	            'payment_method_id' => $paymentMethodId,
337	            'setup_intent_id' => $setupIntentId,
338	        ];
