3	namespace App\Models\Core\Professional;
4	
5	use App\Models\BaseModel;
6	use Illuminate\Database\Eloquent\Concerns\HasUuids;
7	use Illuminate\Database\Eloquent\Relations\BelongsTo;
8	use Illuminate\Support\Arr;
9	
10	// V2: OAuth integration record (Square, Fresha, Shopify). Stores encrypted tokens and provider_metadata (webhook IDs, collection handles, etc.).
11	class ProfessionalIntegration extends BaseModel
12	{
13	    use HasUuids;
14	
15	    public const PROVIDER_SQUARE = 'square';
16	
17	    public const PROVIDER_FRESHA = 'fresha';
18	
19	    public const PROVIDER_SHOPIFY = 'shopify';
20	
21	    protected $table = 'core.professional_integrations';
22	
23	    public $incrementing = false;
24	
25	    protected $keyType = 'string';
26	
27	    protected $hidden = [
28	        'access_token',
29	        'refresh_token',
30	        'storefront_token',
31	        'provider_metadata',
32	    ];
33	
34	    protected $fillable = [
35	        'professional_id',
36	        'provider',
37	        'external_account_id',
38	        'access_token',
39	        'refresh_token',
40	        'storefront_token',
41	        'expires_at',
42	        'catalog_latest_time',
43	        'last_catalog_sync_at',
44	        'last_catalog_sync_error',
45	        'provider_metadata',
46	    ];
47	
48	    protected $casts = [
49	        'access_token' => 'encrypted',
50	        'refresh_token' => 'encrypted',
51	        'storefront_token' => 'encrypted',
52	        'expires_at' => 'datetime',
53	        'catalog_latest_time' => 'datetime',
54	        'last_catalog_sync_at' => 'datetime',
55	        'provider_metadata' => 'array',
56	    ];
57	
58	    public function professional(): BelongsTo
59	    {
60	        return $this->belongsTo(Professional::class, 'professional_id');
61	    }
62	
63	    public function scopeProvider($query, string $provider)
64	    {
65	        return $query->where('provider', mb_strtolower(trim($provider)));
66	    }
67	
68	    /**
69	     * Summarise the Shopify post-install pipeline state from provider_metadata.
70	     *
71	     * Each of the 5 install jobs writes a per-step state key on success ('registered'
72	     * or 'synced') and 'failed' on permanent failure. Missing keys mean the job is
73	     * still pending (queued or in-flight).
74	     *
75	     * @return array{state: string, steps: array<string, string|null>}
76	     *   state  — 'complete' | 'incomplete' | 'pending'
77	     *   steps  — per-job state values keyed by step name
78	     */
79	    public function shopifyInstallStatus(): array
80	    {
81	        $metadata = is_array($this->provider_metadata) ? $this->provider_metadata : [];
82	
83	        $steps = [
84	            'webhooks'         => Arr::get($metadata, 'webhooks_state'),
85	            'metafields'       => Arr::get($metadata, 'metafield_definitions_state'),
86	            'sales_channel'    => Arr::get($metadata, 'sales_channel_state'),
87	            'storefront_token' => Arr::get($metadata, 'storefront_token_state'),
88	            'brand_design'     => Arr::get($metadata, 'brand_design_state'),
89	        ];
90	
91	        $allComplete = true;
92	        $anyFailed = false;
93	
94	        foreach ($steps as $state) {
95	            if ($state !== 'registered' && $state !== 'synced') {
96	                $allComplete = false;
97	                if ($state === 'failed' || $state === 'partial') {
98	                    $anyFailed = true;
99	                }
100	            }
101	        }
102	
103	        return [
104	            'state' => $allComplete ? 'complete' : ($anyFailed ? 'incomplete' : 'pending'),
105	            'steps' => $steps,
106	        ];
107	    }
108	
109	    /**
110	     * Atomically merge keys into provider_metadata without overwriting
111	     * keys written by other concurrent jobs.
112	     *
113	     * Production (pgsql): uses the jsonb `||` merge operator so the update
114	     * is a single atomic statement even under concurrent writes from
115	     * webhooks / onboarding jobs / storefront token creation.
116	     *
117	     * Tests (sqlite, via the pgsql→sqlite redirect in TestCase): falls back
118	     * to a refresh + PHP-side array merge + save. Loss of atomicity is
119	     * acceptable because the test suite is single-process.
120	     */
121	    public function mergeProviderMetadata(array $data): void
122	    {
123	        $connection = $this->getConnection();
124	
125	        if ($connection->getDriverName() === 'pgsql') {
126	            $json = json_encode($data, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
127	
128	            $connection->update(
129	                "UPDATE {$this->getTable()} SET provider_metadata = COALESCE(provider_metadata, '{}'::jsonb) || ?::jsonb, updated_at = ? WHERE id = ?",
130	                [$json, now(), $this->id]
131	            );
132	
133	            $this->refresh();
134	
135	            return;
136	        }
137	
138	        // SQLite fallback: non-atomic but safe in single-process test runs.
139	        $this->refresh();
140	        $current = is_array($this->provider_metadata) ? $this->provider_metadata : [];
141	        $this->provider_metadata = array_merge($current, $data);
142	        $this->save();
143	    }
144	}
