16	        // real Supabase host via DB_HOST and fails with DNS errors. Point the
17	        // 'pgsql' connection at the same in-memory SQLite the test suite uses,
18	        // so models still resolve their forced connection but it goes nowhere
19	        // dangerous.
20	        config(['database.connections.pgsql' => array_merge(
21	            config('database.connections.sqlite'),
22	            ['name' => 'pgsql']
23	        )]);
24	
25	        // Also make pgsql the DEFAULT connection in tests, so unqualified calls
26	        // like DB::table('foo') and DB::statement(...) hit the same PDO handle
27	        // that BaseModel-forced models use. Without this, ATTACH DATABASE and
28	        // CREATE TABLE statements run on a different SQLite handle than the
29	        // models, so models can't see the tables.
30	        config(['database.default' => 'pgsql']);
31	
32	        DB::purge('pgsql');
33	    }
